import{i as e,r as t,s as n,t as r}from"./app-DH4mVKN4.js";var i=JSON.parse(`{"path":"/md/hack/tools/2022-04-17-005-Zmap.html","title":"Zmap","lang":"zh-CN","frontmatter":{"category":"binghe-code-hack","title":"Zmap","tagline":"by 冰河","tag":["hack","binghe-code-hack"],"excerpt":"Zmap","lock":"need"},"git":{"updatedTime":1777440209000,"contributors":[{"name":"binghe001","username":"binghe001","email":"“1028386804@qq.com”","commits":1,"url":"https://github.com/binghe001"},{"name":"Claude Sonnet 4.6","username":"","email":"noreply@anthropic.com","commits":1}],"changelog":[{"hash":"dfed50e61131b09c729d1e8ca8a6567f91a521cf","time":1777440209000,"email":"“1028386804@qq.com”","author":"binghe001","message":"Merge feature/upgrade-vuepress2: fix search box position and layout","coAuthors":[{"name":"Claude Sonnet 4.6","email":"noreply@anthropic.com"}]}]},"filePathRelative":"md/hack/tools/2022-04-17-005-Zmap.md"}`),a={name:`2022-04-17-005-Zmap.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="zmap" tabindex="-1"><a class="header-anchor" href="#zmap"><span>Zmap</span></a></h1><h2 id="初识-zmap" tabindex="-1"><a class="header-anchor" href="#初识-zmap"><span>初识 ZMap</span></a></h2><p>ZMap被设计用来针对整个IPv4地址空间或其中的大部分实施综合扫描的工具。ZMap是研究者手中的利器，但在运行ZMap时，请注意，您很有 可能正在以每秒140万个包的速度扫描整个IPv4地址空间 。我们建议用户即使在实施小范围扫描之前，也联系一下本地网络的管理员并参考我们列举的最佳扫描体验。</p><p>默认情况下，ZMap会对于指定端口实施尽可能大速率的TCP SYN扫描。较为保守的情况下，对10,000个随机的地址的80端口以10Mbps的速度扫描，如下所示：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">$ zmap --bandwidth=10M --target-port=80 --max-targets=10000 --output-file=results.csv</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>或者更加简洁地写成：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">$ zmap -B 10M -p 80 -n 10000 -o results.csv</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>ZMap也可用于扫描特定子网或CIDR地址块。例如，仅扫描10.0.0.0/8和192.168.0.0/16的80端口，运行指令如下：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">zmap -p 80 -o results.csv 10.0.0.0/8 192.168.0.0/16</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>如果扫描进行的顺利，ZMap会每秒输出类似以下内容的状态更新：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">0% (1h51m left); send: 28777 562 Kp/s (560 Kp/s avg); recv: 1192 248 p/s (231 p/s avg); hits: 0.04%</span>
<span class="line">0% (1h51m left); send: 34320 554 Kp/s (559 Kp/s avg); recv: 1442 249 p/s (234 p/s avg); hits: 0.04%</span>
<span class="line">0% (1h50m left); send: 39676 535 Kp/s (555 Kp/s avg); recv: 1663 220 p/s (232 p/s avg); hits: 0.04%</span>
<span class="line">0% (1h50m left); send: 45372 570 Kp/s (557 Kp/s avg); recv: 1890 226 p/s (232 p/s avg); hits: 0.04%</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>这些更新信息提供了扫描的即时状态并表示成：</p><p>完成进度% (剩余时间); send: 发出包的数量 即时速率 (平均发送速率); recv: 接收包的数量 接收率 (平均接收率); hits: 命中率</p><p>如果不知道所在网络能支持的扫描速率，您可能要尝试不同的扫描速率和带宽限制直到扫描效果开始下降，借此找出当前网络能够支持的最快速度。</p><p>默认情况下，ZMap会输出不同IP地址的列表（例如，根据SYN ACK数据包的情况），像下面这样。其输出结果还有几种附加的格式（如，JSON和Redis），可以用作生成程序可解析的扫描统计。 同样，可以指定附加的输出字段并使用输出过滤来过滤输出的结果。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">115.237.116.119</span>
<span class="line">23.9.117.80</span>
<span class="line">207.118.204.141</span>
<span class="line">217.120.143.111</span>
<span class="line">50.195.22.82</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>我们强烈建议您使用黑名单文件，以排除预留的/未分配的IP地址空间（如，RFC1918 规定的私有地址、组播地址），以及网络中需要排除在您扫描之外的地址。默认情况下，ZMap将采用位于 /etc/zmap/blacklist.conf的这个简单的黑名单文件中所包含的预留和未分配地址。如果您需要某些特定设置，比如每次运行ZMap时的最大带宽或黑名单文件，您可以在文件/etc/zmap/zmap.conf中指定或使用自定义配置文件。</p><p>如果您正试图解决扫描的相关问题，有几个选项可以帮助您调试。首先，您可以通过添加--dryrun实施预扫，以此来分析包可能会发送到网络的何处。此外，还可以通过设置&#39;--verbosity=n\`来更改日志详细程度。 最佳扫描体验</p><p>我们为针对互联网进行扫描的研究者提供了一些建议，以此来引导养成良好的互联网合作氛围。</p><ul><li>密切协同本地的网络管理员，以减少风险和调查</li><li>确认扫描不会使本地网络或上游供应商瘫痪</li><li>在发起扫描的源地址的网页和DNS条目中申明你的扫描是善意的</li><li>明确解释你的扫描中所有连接的目的和范围</li><li>提供一个简单的退出扫描的方法并及时响应请求</li><li>实施扫描时，不使用比研究对象需求更大的扫描范围或更快的扫描频率</li><li>如果可以，将扫描流量分布到不同的时间或源地址上</li></ul><p>即使不声明，使用扫描的研究者也应该避免利用漏洞或访问受保护的资源，并遵守其辖区内任何特殊的法律规定。 命令行参数</p><h2 id="通用选项" tabindex="-1"><a class="header-anchor" href="#通用选项"><span>通用选项</span></a></h2><p>这些选项是实施简单扫描时最常用的选项。我们注意到某些选项取决于所使用的探测模块或输出模块（如，在实施ICMP Echo扫描时是不需要使用目的端口的）。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">-p, --target-port=port</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>要扫描的目标TCP端口号（例如，443）</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">-o, --output-file=name</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>将结果写入该文件，使用-代表输出到标准输出。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">-b, --blacklist-file=path</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>文件中被排除的子网使用CIDR表示法（如192.168.0.0/16），一个一行。建议您使用此方法排除RFC 1918地址、组播地址、IANA预留空间等IANA专用地址。在conf/blacklist.example中提供了一个以此为目的示例黑名单文件。 扫描选项</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">-n, --max-targets=n</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>限制探测目标的数量。后面跟的可以是一个数字（例如&#39;-n 1000），或可扫描地址空间的百分比（例如，-n 0.1％\`，不包括黑名单）</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">-N, --max-results=n</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>收到多少结果后退出</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">-t, --max-runtime=secs</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>限制发送报文的时间</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">-r, --rate=pps</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>设置发包速率，以包/秒为单位</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">-B, --bandwidth=bps</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>以比特/秒设置传输速率（支持使用后缀G，M或K（如-B 10M就是速度10 mbps）的。设置会覆盖--rate。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">-c, --cooldown-time=secs</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>发送完成后等待多久继续接收回包（默认值= 8）</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">-e, --seed=n</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>地址排序种子。如果要用多个ZMap以相同的顺序扫描地址，那么就可以使用这个参数。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">--shards=n</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>将扫描分片/区，使其可多个ZMap中执行（默认值= 1）。启用分片时，--seed参数是必需的。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">--shard=n</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>选择扫描的分片（默认值= 0）。n的范围在[0，N)，其中N为碎片的总数。启用分片时，--seed参数是必需的。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">-T, --sender-threads=n</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>用于发送数据包的线程数（默认值= 1）</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">-P, --probes=n</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>发送到每个IP的探测数（默认值= 1）</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">-d, --dryrun</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>用标准输出打印出每个包，而不是将其发送（用于调试）</p><p>网络选项</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">-s, --source-port=port|range</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>发送数据包的源端口</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">-S, --source-ip=ip|range</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>发送数据包的源地址。可以仅仅是一个IP，也可以是一个范围（如，10.0.0.1-10.0.0.9）</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">-G, --gateway-mac=addr</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>数据包发送到的网关MAC地址（用以防止自动检测不工作的情况）</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">-i, --interface=name</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>使用的网络接口</p><h2 id="探测选项" tabindex="-1"><a class="header-anchor" href="#探测选项"><span>探测选项</span></a></h2><p>ZMap允许用户指定并添加自己所需要的探测模块。 探测模块的职责就是生成要发送的探测包，并处理主机回复的响应包。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">--list-probe-modules</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>列出可用探测模块（如tcp_synscan）</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">-M, --probe-module=name</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>选择探测模块（默认值= tcp_synscan）</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">--probe-args=args</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>向模块传递参数</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">--list-output-fields</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>列出可用的输出模块</p><h2 id="输出选项" tabindex="-1"><a class="header-anchor" href="#输出选项"><span>输出选项</span></a></h2><p>ZMap允许用户指定和编写他们自己的输出模块。输出模块负责处理由探测模块返回的字段，并将它们输出给用户。用户可以指定输出的字段，并过滤相应字段。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">--list-output-modules</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>列出可用输出模块（如tcp_synscan）</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">-O, --output-module=name</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>选择输出模块（默认值为csv）</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">--output-args=args</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>传递给输出模块的参数</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">-f, --output-fields=fields</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>输出的字段列表，以逗号分割</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">--output-filter</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>指定输出过滤器对探测模块定义字段进行过滤 附加选项</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">-C, --config=filename</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>加载配置文件，可以指定其他路径。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">-q, --quiet</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>不必每秒刷新输出</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">-g, --summary</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>在扫描结束后打印配置和结果汇总信息</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">-v, --verbosity=n</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>日志详细程度（0-5，默认值= 3）</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">-h, --help</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>打印帮助并退出</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">-V, --version</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>打印版本并退出</p><h2 id="附加信息" tabindex="-1"><a class="header-anchor" href="#附加信息"><span>附加信息</span></a></h2><p>TCP SYN 扫描</p><p>在执行TCP SYN扫描时，ZMap需要指定一个目标端口，也支持指定发起扫描的源端口范围。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">-p, --target-port=port</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>扫描的TCP端口（例如 443）</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">-s, --source-port=port|range</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>发送扫描数据包的源端口（例如 40000-50000）</p><p>警示！ ZMap基于Linux内核使用RST包来应答SYN/ACK包响应，以关闭扫描器打开的连接。ZMap是在Ethernet层完成包的发送的，这样做是为了减少跟踪打开的TCP连接和路由寻路带来的内核开销。因此，如果您有跟踪连接建立的防火墙规则，如类似于-A INPUT -m state --state RELATED,ESTABLISHED -j ACCEPT的netfilter规则，将阻止SYN/ACK包到达内核。这不会妨碍到ZMap记录应答，但它会阻止RST包被送回，最终被扫描主机的连接会一直打开，直到超时后断开。我们强烈建议您在执行ZMap时，选择一组主机上未使用且防火墙允许访问的端口，加在-s后（如 -s &#39;50000-60000&#39; ）。 ICMP Echo 请求扫描</p><p>虽然在默认情况下ZMap执行的是TCP SYN扫描，但它也支持使用ICMP echo请求扫描。在这种扫描方式下ICMP echo请求包被发送到每个主机，并以收到ICMP应答包作为答复。实施ICMP扫描可以通过选择icmp_echoscan扫描模块来执行，如下：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">$ zmap --probe-module=icmp_echoscan</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h2 id="udp-数据报扫描" tabindex="-1"><a class="header-anchor" href="#udp-数据报扫描"><span>UDP 数据报扫描</span></a></h2><p>ZMap还额外支持UDP探测，它会发出任意UDP数据报给每个主机，并接收UDP或ICMP不可达的应答。ZMap可以通过使用--probe- args命令行选项来设置四种不同的UDP载荷。这些是：可在命令行设置可打印的ASCII 码的‘text’载荷和十六进制载荷的‘hex’，外部文件中包含载荷的‘file’，和通过动态字段生成的载荷的‘template’。为了得到UDP 响应，请使用-f参数确保您指定的“data”字段处于输出范围。</p><p>下面的例子将发送两个字节&#39;ST&#39;，即PCAnwywhere的&#39;status&#39;请求，到UDP端口5632。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">$ zmap -M udp -p 5632 --probe-args=text:ST -N 100 -f saddr,data -o -</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>下面的例子将发送字节“0X02”，即SQL Server的&#39;client broadcast&#39;请求，到UDP端口1434。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">$ zmap -M udp -p 1434 --probe-args=hex:02 -N 100 -f saddr,data -o -</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>下面的例子将发送一个NetBIOS状态请求到UDP端口137。使用一个ZMap自带的载荷文件。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">$ zmap -M udp -p 1434 --probe-args=file:netbios_137.pkt -N 100 -f saddr,data -o -</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>下面的例子将发送SIP的&#39;OPTIONS&#39;请求到UDP端口5060。使用附ZMap自带的模板文件。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">$ zmap -M udp -p 1434 --probe-args=file:sip_options.tpl -N 100 -f saddr,data -o -</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>UDP载荷模板仍处于实验阶段。当您在更多的使用一个以上的发送线程（-T）时可能会遇到崩溃和一个明显的相比静态载荷性能降低的表现。模板仅仅是 一个由一个或多个使用\${}将字段说明封装成序列构成的载荷文件。某些协议，特别是SIP，需要载荷来反射包中的源和目的包。其他协议，如 portmapper和DNS，每个请求包含的字段应该是随机的，或降低被Zamp扫描的多宿主系统的风险。</p><p>以下的载荷模板将发送SIP OPTIONS请求到每一个目的地：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">OPTIONS sip:\${RAND_ALPHA=8}@\${DADDR} SIP/2.0</span>
<span class="line">Via: SIP/2.0/UDP \${SADDR}:\${SPORT};branch=\${RAND_ALPHA=6}.\${RAND_DIGIT=10};rport;alias</span>
<span class="line">From: sip:\${RAND_ALPHA=8}@\${SADDR}:\${SPORT};tag=\${RAND_DIGIT=8}</span>
<span class="line">To: sip:\${RAND_ALPHA=8}@\${DADDR}</span>
<span class="line">Call-ID: \${RAND_DIGIT=10}@\${SADDR}</span>
<span class="line">CSeq: 1 OPTIONS</span>
<span class="line">Contact: sip:\${RAND_ALPHA=8}@\${SADDR}:\${SPORT}</span>
<span class="line">Content-Length: 0</span>
<span class="line">Max-Forwards: 20</span>
<span class="line">User-Agent: \${RAND_ALPHA=8}</span>
<span class="line">Accept: text/plain</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>就像在上面的例子中展示的那样，注意每行行末以\\r\\n结尾，请求以\\r\\n\\r\\n结尾，大多数SIP实现都可以正确处理它。一个可以工作的例子放在ZMap的examples/udp-payloads目录下 (sip_options.tpl).</p><p>当前实现了下面的模板字段：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">SADDR: 源IP地址的点分十进制格式</span>
<span class="line">SADDR_N: 源IP地址的网络字节序格式</span>
<span class="line">DADDR: 目的IP地址的点分十进制格式</span>
<span class="line">DADDR_N: 目的IP地址的网络字节序格式</span>
<span class="line">SPORT: 源端口的ascii格式</span>
<span class="line">SPORT_N: 源端口的网络字节序格式</span>
<span class="line">DPORT: 目的端口的ascii格式</span>
<span class="line">DPORT_N: 目的端口的网络字节序格式</span>
<span class="line">RAND_BYTE: 随机字节(0-255)，长度由=(length) 参数决定</span>
<span class="line">RAND_DIGIT: 随机数字0-9，长度由=(length) 参数决定</span>
<span class="line">RAND_ALPHA: 随机大写字母A-Z，长度由=(length) 参数决定</span>
<span class="line">RAND_ALPHANUM: 随机大写字母A-Z和随机数字0-9，长度由=(length) 参数决定</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>配置文件</p><p>ZMap支持使用配置文件来代替在命令行上指定所有要求的选项。配置中可以通过每行指定一个长名称的选项和对应的值来创建：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">interface &quot;eth1&quot;</span>
<span class="line">source-ip 1.1.1.4-1.1.1.8</span>
<span class="line">gateway-mac b4:23:f9:28:fa:2d # upstream gateway</span>
<span class="line">cooldown-time 300 # seconds</span>
<span class="line">blacklist-file /etc/zmap/blacklist.conf</span>
<span class="line">output-file ~/zmap-output</span>
<span class="line">quiet</span>
<span class="line">summary</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>然后ZMap就可以按照配置文件并指定一些必要的附加参数运行了：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">$ zmap --config=~/.zmap.conf --target-port=443</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>详细</p><p>ZMap可以在屏幕上生成多种类型的输出。默认情况下，Zmap将每隔1秒打印出相似的基本进度信息。可以通过设置--quiet来禁用。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">0:01 12%; send: 10000 done (15.1 Kp/s avg); recv: 144 143 p/s (141 p/s avg); hits: 1.44%</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>ZMap同样也可以根据扫描配置打印如下消息，可以通过&#39;--verbosity\`参数加以控制。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">Aug 11 16:16:12.813 [INFO] zmap: started</span>
<span class="line">Aug 11 16:16:12.817 [DEBUG] zmap: no interface provided. will use eth0</span>
<span class="line">Aug 11 16:17:03.971 [DEBUG] cyclic: primitive root: 3489180582</span>
<span class="line">Aug 11 16:17:03.971 [DEBUG] cyclic: starting point: 46588</span>
<span class="line">Aug 11 16:17:03.975 [DEBUG] blacklist: 3717595507 addresses allowed to be scanned</span>
<span class="line">Aug 11 16:17:03.975 [DEBUG] send: will send from 1 address on 28233 source ports</span>
<span class="line">Aug 11 16:17:03.975 [DEBUG] send: using bandwidth 10000000 bits/s, rate set to 14880 pkt/s</span>
<span class="line">Aug 11 16:17:03.985 [DEBUG] recv: thread started</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>ZMap还支持在扫描之后打印出一个的可grep的汇总信息，类似于下面这样，可以通过调用--summary来实现。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">cnf target-port 443</span>
<span class="line">cnf source-port-range-begin 32768</span>
<span class="line">cnf source-port-range-end 61000</span>
<span class="line">cnf source-addr-range-begin 1.1.1.4</span>
<span class="line">cnf source-addr-range-end 1.1.1.8</span>
<span class="line">cnf maximum-packets 4294967295</span>
<span class="line">cnf maximum-runtime 0</span>
<span class="line">cnf permutation-seed 0</span>
<span class="line">cnf cooldown-period 300</span>
<span class="line">cnf send-interface eth1</span>
<span class="line">cnf rate 45000</span>
<span class="line">env nprocessors 16</span>
<span class="line">exc send-start-time Fri Jan 18 01:47:35 2013</span>
<span class="line">exc send-end-time Sat Jan 19 00:47:07 2013</span>
<span class="line">exc recv-start-time Fri Jan 18 01:47:35 2013</span>
<span class="line">exc recv-end-time Sat Jan 19 00:52:07 2013</span>
<span class="line">exc sent 3722335150</span>
<span class="line">exc blacklisted 572632145</span>
<span class="line">exc first-scanned 1318129262</span>
<span class="line">exc hit-rate 0.874102</span>
<span class="line">exc synack-received-unique 32537000</span>
<span class="line">exc synack-received-total 36689941</span>
<span class="line">exc synack-cooldown-received-unique 193</span>
<span class="line">exc synack-cooldown-received-total 1543</span>
<span class="line">exc rst-received-unique 141901021</span>
<span class="line">exc rst-received-total 166779002</span>
<span class="line">adv source-port-secret 37952</span>
<span class="line">adv permutation-gen 4215763218</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="结果输出" tabindex="-1"><a class="header-anchor" href="#结果输出"><span>结果输出</span></a></h2><p>ZMap可以通过输出模块生成不同格式的结果。默认情况下，ZMap只支持csv的输出，但是可以通过编译支持redis和json 。可以使用输出过滤来过滤这些发送到输出模块上的结果。输出模块输出的字段由用户指定。默认情况如果没有指定输出文件，ZMap将以csv格式返回结果，而不会生成特定结果。也可以编写自己的输出模块;请参阅编写输出模块。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">-o, --output-file=p</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>输出写入文件地址</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">-O, --output-module=p</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>调用自定义输出模块</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">-f, --output-fields=p</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>以逗号分隔的输出的字段列表</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">--output-filter=filter</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>对给定的探测指定字段输出过滤</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">--list-output-modules</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>列出可用输出模块</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">--list-output-fields</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>列出给定的探测的可用输出字段</p><h2 id="输出字段" tabindex="-1"><a class="header-anchor" href="#输出字段"><span>输出字段</span></a></h2><p>除了IP地址之外，ZMap有很多字段。这些字段可以通过在给定探测模块上运行--list-output-fields来查看。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">$ zmap --probe-module=&quot;tcp_synscan&quot; --list-output-fields</span>
<span class="line">saddr string: 应答包中的源IP地址</span>
<span class="line">saddr-raw int: 网络字节格式的源IP地址</span>
<span class="line">daddr string: 应答包中的目的IP地址</span>
<span class="line">daddr-raw int: 网络字节格式的目的IP地址</span>
<span class="line">ipid int: 应答包中的IP识别号</span>
<span class="line">ttl int: 应答包中的ttl（存活时间）值</span>
<span class="line">sport int: TCP 源端口</span>
<span class="line">dport int: TCP 目的端口</span>
<span class="line">seqnum int: TCP 序列号</span>
<span class="line">acknum int: TCP Ack号</span>
<span class="line">window int: TCP 窗口</span>
<span class="line">classification string: 包类型</span>
<span class="line">success int: 是应答包成功</span>
<span class="line">repeat int: 是否是来自主机的重复响应</span>
<span class="line">cooldown int: 是否是在冷却时间内收到的响应</span>
<span class="line">timestamp-str string: 响应抵达时的时间戳使用ISO8601格式</span>
<span class="line">timestamp-ts int: 响应抵达时的时间戳使用UNIX纪元开始的秒数</span>
<span class="line">timestamp-us int: 时间戳的微秒部分(例如 从&#39;timestamp-ts&#39;的几微秒)</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>可以通过使用--output-fields=fields或-f来选择选择输出字段，任意组合的输出字段可以被指定为逗号分隔的列表。例如：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">$ zmap -p 80 -f &quot;response,saddr,daddr,sport,seq,ack,in_cooldown,is_repeat,timestamp&quot; -o output.csv</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h2 id="过滤输出" tabindex="-1"><a class="header-anchor" href="#过滤输出"><span>过滤输出</span></a></h2><p>在传到输出模块之前，探测模块生成的结果可以先过滤。过滤是针对探测模块的输出字段的。过滤使用类似于SQL的简单过滤语法写成，通过ZMap的--output-filter选项来指定。输出过滤通常用于过滤掉重复的结果，或仅传输成功的响应到输出模块。</p><p>过滤表达式的形式为&lt;字段名&gt; &lt;操作符&gt; &lt;值&gt;。&lt;值&gt;的类型必须是一个字符串或一串无符号整数并且匹配&lt;字段名&gt;类型。对于整数比较有效的操作符是= !=, &lt;, &gt;, &lt;=, &gt;=。字符串比较的操作是=，!=。--list-output-fields可以打印那些可供探测模块选择的字段和类型，然后退出。</p><p>复合型的过滤操作，可以通过使用&amp;&amp;（逻辑与）和||（逻辑或）这样的运算符来组合出特殊的过滤操作。</p><p>示例</p><p>书写一则过滤仅显示成功的、不重复的应答</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">--output-filter=&quot;success = 1 &amp;&amp; repeat = 0&quot;</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>过滤出RST分类并且TTL大于10的包，或者SYNACK分类的包</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">--output-filter=&quot;(classification = rst &amp;&amp; ttl &gt; 10) || classification = synack&quot;</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>CSV</p><p>csv模块将会生成以逗号分隔各个要求输出的字段的文件。例如，以下的指令将生成名为output.csv的CSV文件。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">$ zmap -p 80 -f &quot;response,saddr,daddr,sport,seq,ack,in_cooldown,is_repeat,timestamp&quot; -o output.csv</span>
<span class="line"></span>
<span class="line">#响应, 源地址, 目的地址, 源端口, 目的端口, 序列号, 应答, 是否是冷却模式, 是否重复, 时间戳</span>
<span class="line">response, saddr, daddr, sport, dport, seq, ack, in_cooldown, is_repeat, timestamp</span>
<span class="line">synack, 159.174.153.144, 10.0.0.9, 80, 40555, 3050964427, 3515084203, 0, 0,2013-08-15 18:55:47.681</span>
<span class="line">rst, 141.209.175.1, 10.0.0.9, 80, 40136, 0, 3272553764, 0, 0,2013-08-15 18:55:47.683</span>
<span class="line">rst, 72.36.213.231, 10.0.0.9, 80, 56642, 0, 2037447916, 0, 0,2013-08-15 18:55:47.691</span>
<span class="line">rst, 148.8.49.150, 10.0.0.9, 80, 41672, 0, 1135824975, 0, 0,2013-08-15 18:55:47.692</span>
<span class="line">rst, 50.165.166.206, 10.0.0.9, 80, 38858, 0, 535206863, 0, 0,2013-08-15 18:55:47.694</span>
<span class="line">rst, 65.55.203.135, 10.0.0.9, 80, 50008, 0, 4071709905, 0, 0,2013-08-15 18:55:47.700</span>
<span class="line">synack, 50.57.166.186, 10.0.0.9, 80, 60650, 2813653162, 993314545, 0, 0,2013-08-15 18:55:47.704</span>
<span class="line">synack, 152.75.208.114, 10.0.0.9, 80, 52498, 460383682, 4040786862, 0, 0,2013-08-15 18:55:47.707</span>
<span class="line">synack, 23.72.138.74, 10.0.0.9, 80, 33480, 810393698, 486476355, 0, 0,2013-08-15 18:55:47.710</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="redis" tabindex="-1"><a class="header-anchor" href="#redis"><span>Redis</span></a></h2><p>Redis的输出模块允许地址被添加到一个Redis的队列，而不是保存到文件，允许ZMap将它与之后的处理工具结合使用。</p><p>注意! ZMap默认不会编译Redis功能。如果你从源码构建ZMap，可以在CMake的时候加上-DWITH_REDIS=ON来增加Redis支持。</p><h2 id="json" tabindex="-1"><a class="header-anchor" href="#json"><span>JSON</span></a></h2><p>JSON输出模块用起来类似于CSV模块，只是以JSON格式写入到文件。JSON文件能轻松地导入到其它可以读取JSON的程序中。</p><p>注意！，ZMap默认不会编译JSON功能。如果你从源码构建ZMap，可以在CMake的时候加上-DWITH_JSON=ON来增加JSON支持。</p><h2 id="黑名单和白名单" tabindex="-1"><a class="header-anchor" href="#黑名单和白名单"><span>黑名单和白名单</span></a></h2><p>ZMap同时支持对网络前缀做黑名单和白名单。如果ZMap不加黑名单和白名单参数，他将会扫描所有的IPv4地址（包括本地的，保留的以及组播地 址）。如果指定了黑名单文件，那么在黑名单中的网络前缀将不再扫描；如果指定了白名单文件，只有那些网络前缀在白名单内的才会扫描。白名单和黑名单文件可 以协同使用；黑名单优先于白名单（例如：如果您在白名单中指定了10.0.0.0/8并在黑名单中指定了10.1.0.0/16，那么10.1.0.0 /16将不会扫描）。白名单和黑名单文件可以在命令行中指定，如下所示：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">-b, --blacklist-file=path</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>文件用于记录黑名单子网，以CIDR（无类域间路由）的表示法，例如192.168.0.0/16</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">-w, --whitelist-file=path</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>文件用于记录限制扫描的子网，以CIDR的表示法，例如192.168.0.0/16</p><p>黑名单文件的每行都需要以CIDR的表示格式书写，一行单一的网络前缀。允许使用#加以备注。例如：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line"># IANA（英特网编号管理局）记录的用于特殊目的的IPv4地址</span>
<span class="line"># http://www.iana.org/assignments/iana-ipv4-special-registry/iana-ipv4-special-registry.xhtml</span>
<span class="line"># 更新于2013-05-22</span>
<span class="line">0.0.0.0/8 # RFC1122: 网络中的所有主机</span>
<span class="line">10.0.0.0/8 # RFC1918: 私有地址</span>
<span class="line">100.64.0.0/10 # RFC6598: 共享地址空间</span>
<span class="line">127.0.0.0/8 # RFC1122: 回环地址</span>
<span class="line">169.254.0.0/16 # RFC3927: 本地链路地址</span>
<span class="line">172.16.0.0/12 # RFC1918: 私有地址</span>
<span class="line">192.0.0.0/24 # RFC6890: IETF协议预留</span>
<span class="line">192.0.2.0/24 # RFC5737: 测试地址1</span>
<span class="line">192.88.99.0/24 # RFC3068: IPv6转换到IPv4的任播</span>
<span class="line">192.168.0.0/16 # RFC1918: 私有地址</span>
<span class="line">192.18.0.0/15 # RFC2544: 检测地址</span>
<span class="line">198.51.100.0/24 # RFC5737: 测试地址2</span>
<span class="line">203.0.113.0/24 # RFC5737: 测试地址3</span>
<span class="line">240.0.0.0/4 # RFC1112: 预留地址</span>
<span class="line">255.255.255.255/32 # RFC0919: 限制广播地址</span>
<span class="line"># IANA记录的用于组播的地址空间</span>
<span class="line"># http://www.iana.org/assignments/multicast-addresses/multicast-addresses.xhtml</span>
<span class="line"># 更新于2013-06-25</span>
<span class="line">224.0.0.0/4 # RFC5771: 组播/预留地址ed</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>如果您只是想扫描因特网中随机的一部分地址，使用抽样检出，来代替使用白名单和黑名单。</p><p>注意！ZMap默认设置使用/etc/zmap/blacklist.conf作为黑名单文件，其中包含有本地的地址空间和预留的IP空间。通过编辑/etc/zmap/zmap.conf可以改变默认的配置。</p><h2 id="速度限制与抽样" tabindex="-1"><a class="header-anchor" href="#速度限制与抽样"><span>速度限制与抽样</span></a></h2><p>默认情况下，ZMap将以您当前网卡所能支持的最快速度扫描。以我们对于常用硬件的经验，这通常是理论上Gbit以太网速度的95-98%，这可能 比您的上游提供商可处理的速度还要快。ZMap是不会自动的根据您的上游提供商来调整发送速率的。您可能需要手动的调整发送速率来减少丢包和错误结果。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">-r, --rate=pps</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>设置最大发送速率以包/秒为单位</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">-B, --bandwidth=bps</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>设置发送速率以比特/秒(支持G,M和K后缀)。这会覆盖--rate参数。</p><p>ZMap同样支持对IPv4地址空间进行指定最大目标数和/或最长运行时间的随机采样。由于每次对主机的扫描是通过随机排序生成的，限制扫描的主机个数为N就会随机抽选N个主机。命令选项如下：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">-n, --max-targets=n</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>探测目标上限数量</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">-N, --max-results=n</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>结果上限数量（累积收到这么多结果后退出）</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">-t, --max-runtime=s</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>发送数据包时间长度上限（以秒为单位）</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">-s, --seed=n</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>种子用以选择地址的排列方式。使用不同ZMap执行扫描操作时将种子设成相同的值可以保证相同的扫描顺序。</p><p>举个例子，如果您想要多次扫描同样的一百万个互联网主机，可以设定排序种子和扫描主机的上限数量，大致如下所示：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">zmap -p 443 -s 3 -n 1000000 -o results</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>为了确定哪一百万主机将要被扫描，您可以执行预扫，只打印数据包而非发送，并非真的实施扫描。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">zmap -p 443 -s 3 -n 1000000 --dryrun | grep daddr</span>
<span class="line">| awk -F&#39;daddr: &#39; &#39;{print $2}&#39; | sed &#39;s/ |.*//;&#39;</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="发送多个数据包" tabindex="-1"><a class="header-anchor" href="#发送多个数据包"><span>发送多个数据包</span></a></h2><p>ZMap支持向每个主机发送多个探测。增加这个数量既增加了扫描时间又增加了到达的主机数量。然而，我们发现，增加的扫描时间（每个额外扫描的增加近100％）远远大于到达的主机数量（每个额外扫描的增加近1％）。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">-P, --probes=n</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>向每个IP发出的独立探测个数（默认值=1）</p><h2 id="示例应用" tabindex="-1"><a class="header-anchor" href="#示例应用"><span>示例应用</span></a></h2><p>ZMap专为向大量主机发起连接并寻找那些正确响应而设计。然而，我们意识到许多用户需要执行一些后续处理，如执行应用程序级别的握手。例如，用户在80端口实施TCP SYN扫描也许想要实施一个简单的GET请求，还有用户扫描443端口可能希望完成TLS握手。</p><p><strong>Banner获取</strong></p><p>我收录了一个示例程序，banner-grab，伴随ZMap使用可以让用户从监听状态的TCP服务器上接收到消息。Banner-grab连接 到提供的服务器上，发送一个可选的消息，然后打印出收到的第一个消息。这个工具可以用来获取banner，例如HTTP服务的回复的具体指 令，telnet登陆提示，或SSH服务的字符串。</p><p>下面的例子寻找了1000个监听80端口的服务器，并向每个发送一个简单的GET请求，存储他们的64位编码响应至http-banners.out</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">$ zmap -p 80 -N 1000 -B 10M -o - | ./banner-grab-tcp -p 80 -c 500 -d ./http-req &gt; out</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>如果想知道更多使用banner-grab的细节,可以参考examples/banner-grab中的README文件。</p><p>注意！ ZMap和banner-grab（如例子中）同时运行可能会比较显著的影响对方的表现和精度。确保不让ZMap占满banner-grab-tcp的并 发连接，不然banner-grab将会落后于标准输入的读入，导致阻塞ZMap的输出写入。我们推荐使用较慢扫描速率的ZMap，同时提升 banner-grab-tcp的并发性至3000以内（注意 并发连接&gt;1000需要您使用ulimit -SHn 100000和ulimit -HHn 100000来增加每个进程的最大文件描述符数量）。当然，这些参数取决于您服务器的性能、连接成功率（hit-rate）；我们鼓励开发者在运行大型扫描之前先进行小样本的试验。 建立套接字</p><p>我们也收录了另一种形式的banner-grab，就是forge-socket， 重复利用服务器发出的SYN-ACK，连接并最终取得banner。在banner-grab-tcp中，ZMap向每个服务器发送一个SYN，并监听服务器发回的带有SYN+ACK的应答。运行ZMap主机的内核接受应答后发送RST，这样就没有与该包关联活动连接。程序banner-grab必须在这之后创建一个新的TCP连接到从服务器获取数据。</p><p>在forge-socket中，我们利用内核中同名的模块，使我们可以创建任意参数的TCP连接。可以通过抑制内核的RST包，并重用SYN+ACK的参数取代该包而创建套接字，通过这个套接字收发数据和我们平时使用的连接套接字并没有什么不同。</p><p>要使用forge-socket，您需要forge-socket内核模块，从github上可以获得。您需要git clone <a href="mailto:git@github.com" target="_blank" rel="noopener noreferrer">git@github.com</a>:ewust/forge_socket.git至ZMap源码根目录，然后cd进入forge_socket目录，运行make。以root身份运行insmod forge_socket.ko 来安装该内核模块。</p><p>您也需要告知内核不要发送RST包。一个简单的在全系统禁用RST包的方法是使用iptables。以root身份运行iptables -A OUTPUT -p tcp -m tcp --tcp-flgas RST,RST RST,RST -j DROP即可，当然您也可以加上一项--dport X将禁用局限于所扫描的端口（X）上。扫描完成后移除这项设置，以root身份运行iptables -D OUTPUT -p tcp -m tcp --tcp-flags RST,RST RST,RST -j DROP即可。</p><p>现在应该可以建立forge-socket的ZMap示例程序了。运行需要使用extended_fileZMap输出模块：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">$ zmap -p 80 -N 1000 -B 10M -O extended_file -o - | \\</span>
<span class="line">./forge-socket -c 500 -d ./http-req &gt; ./http-banners.out</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>详细内容可以参考examples/forge-socket目录下的README。</p><h2 id="编写探测和输出模块" tabindex="-1"><a class="header-anchor" href="#编写探测和输出模块"><span>编写探测和输出模块</span></a></h2><p>ZMap可以通过探测模块来扩展支持不同类型的扫描，通过输出模块增加不同类型的输出结果。注册过的探测和输出模块可以在命令行中列出：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">--list-probe-modules</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>列出安装过的探测模块</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">--list-output-modules</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>列出安装过的输出模块</p><h3 id="输出模块" tabindex="-1"><a class="header-anchor" href="#输出模块"><span>输出模块</span></a></h3><p>ZMap的输出和输出后处理可以通过实现和注册扫描器的输出模块来扩展。输出模块在接收每一个应答包时都会收到一个回调。然而默认提供的模块仅提供简单的输出，这些模块同样支持更多的输出后处理（例如：重复跟踪或输出AS号码来代替IP地址）。</p><p>通过定义一个新的output_module结构来创建输出模块，并在output_modules.c中注册：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">typedef struct output_module {</span>
<span class="line">const char *name; // 在命令行如何引用输出模块</span>
<span class="line">unsigned update_interval; // 以秒为单位的更新间隔</span>
<span class="line">output_init_cb init; // 在扫描器初始化的时候调用</span>
<span class="line">output_update_cb start; // 在扫描器开始的时候调用</span>
<span class="line">output_update_cb update; // 每次更新间隔调用，秒为单位</span>
<span class="line">output_update_cb close; // 扫描终止后调用</span>
<span class="line">output_packet_cb process_ip; // 接收到应答时调用</span>
<span class="line">const char *helptext; // 会在--list-output-modules时打印在屏幕上</span>
<span class="line">} output_module_t;</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>输出模块必须有名称，通过名称可以在命令行调用，并且通常会实现success_ip和常见的other_ip回调。process_ip的回调由每个收到并经由probe module过滤的应答包调用。应答是否被认定为成功并不确定（比如，它可以是一个TCP的RST）。这些回调必须定义匹配output_packet_cb定义的函数:</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">int (*output_packet_cb) (</span>
<span class="line">ipaddr_n_t saddr, // 网络字节格式的发起扫描主机IP地址</span>
<span class="line">ipaddr_n_t daddr, // 网络字节格式的目的IP地址</span>
<span class="line">const char* response_type, // 发送模块的数据包分类</span>
<span class="line">int is_repeat, // {0: 主机的第一个应答, 1: 后续的应答}</span>
<span class="line">int in_cooldown, // {0: 非冷却状态, 1: 扫描器处于冷却中}</span>
<span class="line">const u_char* packet, // 指向IP包的iphdr结构体的指针</span>
<span class="line">size_t packet_len // 包的长度，以字节为单位</span>
<span class="line">);</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>输出模块还可以通过注册回调，执行在扫描初始化的时候（诸如打开输出文件的任务）、在扫描开始阶段（诸如记录黑名单的任务）、在扫描的常规间隔（诸如状态更新的任务）、在关闭的时候（诸如关掉所有打开的文件描述符）。提供的这些回调可以完整的访问扫描配置和当前状态：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">int (*output_update_cb)(struct state_conf*, struct state_send*, struct state_recv*);</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>这些定义在output_modules.h中。在src/outputmodules/modulecsv.c中有可用示例。</p><h3 id="探测模块" tabindex="-1"><a class="header-anchor" href="#探测模块"><span>探测模块</span></a></h3><p>数据包由探测模块构造，它可以创建各种包和不同类型的响应。ZMap默认拥有两个扫描模块：tcp_synscan和icmp_echoscan。默认情况下，ZMap使用tcp_synscan来发送TCP SYN包并对每个主机的响应分类，如打开时（收到SYN+ACK）或关闭时（收到RST）。ZMap允许开发者编写自己的ZMap探测模块，使用如下的API：</p><p>任何类型的扫描都必须通过开发和注册send_module_t结构中的回调来实现：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">typedef struct probe_module {</span>
<span class="line">const char *name; // 如何在命令行调用扫描</span>
<span class="line">size_t packet_length; // 探测包有多长(必须是静态的)</span>
<span class="line">const char *pcap_filter; // 对收到的响应实施PCAP过滤</span>
<span class="line">size_t pcap_snaplen; // libpcap 捕获的最大字节数</span>
<span class="line">uint8_t port_args; // 设为1，如果ZMap需要用户指定--target-port</span>
<span class="line">probe_global_init_cb global_initialize; // 在扫描初始化会时被调用一次</span>
<span class="line">probe_thread_init_cb thread_initialize; // 每个包缓存区的线程中被调用一次</span>
<span class="line">probe_make_packet_cb make_packet; // 每个主机更新包的时候被调用一次</span>
<span class="line">probe_validate_packet_cb validate_packet; // 每收到一个包被调用一次，</span>
<span class="line">// 如果包无效返回0，</span>
<span class="line">// 非零则有效。</span>
<span class="line">probe_print_packet_cb print_packet; // 如果在预扫模式下被每个包都调用</span>
<span class="line">probe_classify_packet_cb process_packet; // 由区分响应的接收器调用</span>
<span class="line">probe_close_cb close; // 扫描终止后被调用</span>
<span class="line">fielddef_t *fields // 该模块指定的字段的定义</span>
<span class="line">int numfields // 字段的数量</span>
<span class="line">} probe_module_t;</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>在扫描操作初始化时会调用一次global_initialize，可以用来实施一些必要的全局配置和初始化操作。然而，global_initialize并不能访问包缓冲区，那里是线程特定的。代替的，thread_initialize在 每个发送线程初始化的时候被调用，提供对于缓冲区的访问，可以用来构建探测包和全局的源和目的值。此回调应用于构建主机不可知的包结构，甚至只有特定值 （如：目的主机和校验和），需要随着每个主机更新。例如，以太网头部信息在交换时不会变更（减去校验和是由NIC硬件计算的）因此可以事先定义以减少扫描 时间开销。</p><p>调用回调参数make_packet是为了让被扫描的主机允许探测模块更 新主机指定的值，同时提供IP地址、一个非透明的验证字符串和探测数目（如下所示）。探测模块负责在探测中放置尽可能多的验证字符串，即便当服务器返回的 应答为空时，探测模块也能验证它的当前状态。例如，针对TCP SYN扫描，tcp_synscan探测模块会使用TCP源端口和序列号的格式存储验证字符串。响应包（SYN+ACK）将包含目的端口和确认号的预期 值。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">int make_packet(</span>
<span class="line">void *packetbuf, // 包的缓冲区</span>
<span class="line">ipaddr_n_t src_ip, // 网络字节格式源IP</span>
<span class="line">ipaddr_n_t dst_ip, // 网络字节格式目的IP</span>
<span class="line">uint32_t *validation, // 探测中的有效字符串</span>
<span class="line">int probe_num // 如果向每个主机发送多重探测，</span>
<span class="line">// 该值为我们对于该主机</span>
<span class="line">// 正在发送的探测数目</span>
<span class="line">);</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>扫描模块也应该定义pcap_filter、validate_packet和process_packet。只有符合PCAP过滤器的包才会被扫描。举个例子，在一个TCP SYN扫描的情况下，我们只想要调查TCP SYN / ACK或RST TCP数据包，并利用类似tcp &amp;&amp; tcp[13] &amp; 4 != 0 || tcp[13] == 18的过滤方法。validate_packet函数将会被每个满足PCAP过滤条件的包调用。如果验证返回的值非零，将会调用process_packet函数，并使用fields定义的字段和包中的数据填充字段集。举个例子，如下代码为TCP synscan探测模块处理了一个数据包。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">void synscan_process_packet(const u_char *packet, uint32_t len, fieldset_t *fs){</span>
<span class="line">    struct iphdr *ip_hdr = (struct iphdr *)&amp;packet[sizeof(struct ethhdr)];</span>
<span class="line">    struct tcphdr *tcp = (struct tcphdr*)((char *)ip_hdr + (sizeof(struct iphdr)));</span>
<span class="line">    fs_add_uint64(fs, &quot;sport&quot;, (uint64_t) ntohs(tcp-&gt;source));</span>
<span class="line">    fs_add_uint64(fs, &quot;dport&quot;, (uint64_t) ntohs(tcp-&gt;dest));</span>
<span class="line">    fs_add_uint64(fs, &quot;seqnum&quot;, (uint64_t) ntohl(tcp-&gt;seq));</span>
<span class="line">    fs_add_uint64(fs, &quot;acknum&quot;, (uint64_t) ntohl(tcp-&gt;ack_seq));</span>
<span class="line">    fs_add_uint64(fs, &quot;window&quot;, (uint64_t) ntohs(tcp-&gt;window));</span>
<span class="line">    if (tcp-&gt;rst) { // RST packet</span>
<span class="line">        fs_add_string(fs, &quot;classification&quot;, (char*) &quot;rst&quot;, 0);</span>
<span class="line">        fs_add_uint64(fs, &quot;success&quot;, 0);</span>
<span class="line">    } else { // SYNACK packet</span>
<span class="line">        fs_add_string(fs, &quot;classification&quot;, (char*) &quot;synack&quot;, 0);</span>
<span class="line">        fs_add_uint64(fs, &quot;success&quot;, 1);</span>
<span class="line">    }</span>
<span class="line">}</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="写在最后" tabindex="-1"><a class="header-anchor" href="#写在最后"><span>写在最后</span></a></h2><blockquote><p>如果你觉得冰河写的还不错，请微信搜索并关注「 <strong>冰河技术</strong> 」微信公众号，跟冰河学习高并发、分布式、微服务、大数据、互联网和云原生技术，「 <strong>冰河技术</strong> 」微信公众号更新了大量技术专题，每一篇技术文章干货满满！不少读者已经通过阅读「 <strong>冰河技术</strong> 」微信公众号文章，吊打面试官，成功跳槽到大厂；也有不少读者实现了技术上的飞跃，成为公司的技术骨干！如果你也想像他们一样提升自己的能力，实现技术能力的飞跃，进大厂，升职加薪，那就关注「 <strong>冰河技术</strong> 」微信公众号吧，每天更新超硬核技术干货，让你对如何提升技术能力不再迷茫！</p></blockquote><p><img src="https://img-blog.csdnimg.cn/20200906013715889.png" alt=""></p>`,246)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};